<?php require "../includes/auth.php";require "../config/database.php";$date=$_POST['date']??date('Y-m-d');$statuses=$_POST['status']??[];$q=$pdo->prepare("INSERT INTO attendance(student_id,attendance_date,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)");foreach($statuses as $sid=>$status){if(in_array($status,['Present','Absent'],true))$q->execute([(int)$sid,$date,$status]);}$_SESSION['flash']=['type'=>'success','msg'=>'Attendance saved successfully.'];header("Location:take.php");exit;?>